l":"Shared SCSS DNA every framework speaks."}]}]}},{"id":"home-compiler","type":"section.compiler_demo","order":1,"props":{"railLabel":"Emit","anchorId":"compiler","showSection":true,"showBoard":true,"compilerEyebrow":"Migration in a blink","compilerTitleLead":"Bring the app.","compilerTitleTrail":"Skip the rewrite.","compilerSupport":"Migrate any framework to any other without adapting the project. Convert reads your source as-is - *.nuc.tsx is only an optional connector for shared UI. Domain and Supabase stay in shared_modules.","compilerCta":"Read compiler docs","compilerHub":".vue","compilerHubLabel":"source","compilerEmitLabel":"convert","sourceFile":"InboxBadge.vue","sourceSnippet":"<script setup lang=\"ts\">\nimport { ref, computed } from ''vue''\n\nconst props = defineProps<{ inbox: string }>()\nconst unread = ref(3)\nconst label = computed(() =>\n  unread.value ? `${props.inbox}: ${unread.value}`\n    : ''Caught up'')\nfunction clear() { unread.value = 0 }\n</script>\n\n<template>\n  <nui-button variant=\"filled\" @click=\"clear\">\n    {{ label }}\n  </nui-button>\n</template>","nodes":[{"id":"vue","label":"Vue","icon":"simple-icons:vuedotjs","color":"#42b883","command":"make web --target=vue","file":"InboxBadge.vue","snippet":"<script setup lang=\"ts\">\nimport { ref, computed } from ''vue''\n\nconst props = defineProps<{ inbox: string }>()\nconst unread = ref(3)\nconst label = computed(() =>\n  unread.value ? `${props.inbox}: ${unread.value}`\n    : ''Caught up'')\nfunction clear() { unread.value = 0 }\n</script>\n\n<template>\n  <nui-button variant=\"filled\" @click=\"clear\">\n    {{ label }}\n  </nui-button>\n</template>","x":26,"y":28},{"id":"react","label":"React","icon":"simple-icons:react","color":"#61dafb","command":"make web --target=react","file":"InboxBadge.tsx","snippet":"''use client''\nimport { useState, useMemo, useCallback } from ''react''\n\ntype Props = { inbox: string }\n\nexport default function InboxBadge({ inbox }: Props) {\n  const [unread, setUnread] = useState(3)\n  const label = useMemo(\n    () => (unread ? `${inbox}: ${unread}` : ''Caught up''),\n    [unread, inbox])\n  const clear = useCallback(() => setUnread(0), [])\n  return (\n    <NuiButton variant=\"filled\" onClick={clear}>\n      {label}\n    </NuiButton>\n  )\n}","x":74,"y":28},{"id":"nuxt","label":"Nuxt","icon":"simple-icons:nuxtdotjs","color":"#00dc82","command":"make web --target=nuxt","file":"InboxBadge.vue","snippet":"<script setup lang=\"ts\">\nconst props = defineProps<{ inbox: string }>()\nconst unread = useState(''inbox'', () => 3)\nconst label = computed(() =>\n  unread.value ? `${props.inbox}: ${unread.value}`\n    : ''Caught up'')\n</script>\n\n<template>\n  <nui-button variant=\"filled\" @click=\"unread = 0\">\n    {{ label }}\n  </nui-button>\n</template>","x":18,"y":52},{"id":"next","label":"Next","icon":"simple-icons:nextdotjs","color":"#e8e8e8","command":"make web --target=next","file":"InboxBadge.tsx","snippet":"''use client''\nimport { useState, useMemo } from ''react''\nimport { usePathname } from ''next/navigation''\n\ntype Props = { inbox: string }\n\nexport default function InboxBadge({ inbox }: Props) {\n  const path = usePathname()\n  const [unread, setUnread] = useState(3)\n  const label = useMemo(() =>\n    `${unread ? `${inbox}: ${unread}` : ''Caught up''} · ${path}`,\n    [unread, inbox, path])\n  return (\n    <NuiButton variant=\"filled\" onClick={() => setUnread(0)}>\n      {label}\n    </NuiButton>\n  )\n}","x":82,"y":52},{"id":"astro","label":"Astro","icon":"simple-icons:astro","color":"#ff5d01","command":"make web --target=astro","file":"InboxBadge.astro","snippet":"---\ninterface Props { inbox: string }\nconst { inbox } = Astro.props\n---\n\n<nui-button id=\"badge\" variant=\"filled\" data-inbox={inbox}>\n  {inbox}: 3\n</nui-button>\n\n<script is:inline>\n  const el = document.getElementById(''badge'')\n  let unread = 3\n  const paint = () => {\n    const box = el?.dataset.inbox ?? ''''\n    if (el) el.textContent = unread ? `${box}: ${unread}` : ''Caught up''\n  }\n  el?.addEventListener(\"click\", () => { unread = 0; paint() })\n</script>","x":34,"y":74},{"id":"svelte","label":"Svelte","icon":"simple-icons:svelte","color":"#ff3e00","command":"make web --target=svelte","file":"InboxBadge.svelte","snippet":"<script lang=\"ts\">\n  type Props = { inbox: string }\n  let { inbox }: Props = $props()\n  let unread = $state(3)\n  let label = $derived(\n    unread ? `${inbox}: ${unread}` : ''Caught up'')\n</script>\n\n<nui-button variant=\"filled\" onclick={() => (unread = 0)}>\n  {label}\n</nui-button>","x":66,"y":74},{"id":"solid","label":"Solid","icon":"simple-icons:solid","color":"#72b7eb","command":"make web --target=solid","file":"InboxBadge.tsx","snippet":"import { createSignal, createMemo } from ''solid-js''\n\ntype Props = { inbox: string }\n\nexport default function InboxBadge(props: Props) {\n  const [unread, setUnread] = createSignal(3)\n  const label = createMemo(() =>\n    unread() ? `${props.inbox}: ${unread()}`\n      : ''Caught up'')\n  return (\n    <nui-button variant=\"filled\" onClick={() => setUnread(0)}>\n      {label()}\n    </nui-button>\n  )\n}","x":50,"y":88}]}},{"id":"home-pillars","type":"section.pillars","order":2,"props":{"railLabel":"Ship","anchorId":"architecture","showSection":true,"showShareChart":true,"pillarsEyebrow":"What you actually ship","pillarsTitle":"Bring any framework. Convert to any other.","pillarsSupport":"Migrate any framework to any other without adapting the project for migration. *.nuc.tsx is only an optional connector for shared UI, not a rewrite gate. Domain stays in shared_modules; every framework hits the same Supabase gateway.","pillarsCta":"Pick a framework","pillarsShareUnit":"emit targets","pillarsShareSource":"Any stack in. Seven frameworks out.","items":[{"icon":"mdi:swap-horizontal","index":"01","title":"Any framework → any other","description":"Bring Nuxt, Next, Vue, React, or another supported f